-- Safe rollback: recovery-only public endpoints. No downgrade of fingerprint verification.
-- Keep valid fingerprints, marker and key versions. No new creation until re-upgrade.
create or replace function public.place_order103(p_store uuid, p_items jsonb, p_tip numeric DEFAULT 0, p_payment text DEFAULT 'cash'::text, p_address text DEFAULT ''::text, p_lat double precision DEFAULT NULL::double precision, p_lng double precision DEFAULT NULL::double precision, p_promo text DEFAULT NULL::text, p_key text DEFAULT NULL::text, p_fee numeric DEFAULT NULL::numeric, p_wallet numeric DEFAULT NULL::numeric, p_points integer DEFAULT NULL::integer, p_extra jsonb DEFAULT NULL::jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$begin
 return coalesce(security_private.resolve103(p_key,security_private.request_payload103(p_store,p_items,p_tip,p_payment,p_address,p_lat,p_lng,p_promo,p_fee,p_wallet,p_points,p_extra),true),jsonb_build_object('status','unresolved','reason','rollback_read_only','key',p_key));end$$;
-- Legacy public.place_order wrapper remains in place and therefore also cannot create.

