 return coalesce(security_private.resolve103(p_key,security_private.request_payload103(p_store,p_items,p_tip,p_payment,p_address,p_lat,p_lng,p_promo,p_fee,p_wallet,p_points,p_extra),true),jsonb_build_object('status','unresolved','reason','rollback_read_only','key',p_key));end$$;
